  ELLIPSE: XONLY10,    // 11/21 = ημιάξονας ως προς το κέντρο
  XLINE: XONLY10, RAY: XONLY10,
  LWPOLYLINE: XONLY10, HATCH: XONLY10, LEADER: XONLY10, IMAGE: XONLY10,
