    var ch = b.body[i];
    if (ch[0].v.trim() !== 'LINE') continue;
    var x1 = parseFloat(val(ch, 10)), y1 = parseFloat(val(ch, 20));
    var x2 = parseFloat(val(ch, 11)), y2 = parseFloat(val(ch, 21));
    if (isNaN(x1) || isNaN(y1) || isNaN(x2) || isNaN(y2)) continue;
    L.push([x1, y1, x2, y2]);
